show_method:
public function show(string $locale, ScratchCard $scratchCard)
{
    $this->authorizeMember($scratchCard);
    $scratchCard->load('scratchGame');
    return view('member.scratch-cards.show', compact('scratchCard'));
}

index_method:
public function index()
{
    $member = auth('member')->user();
    $cards = ScratchCard::where('member_id', $member->id)
        ->with('scratchGame')
        ->latest()
        ->paginate(12);

    return view('member.scratch-cards.index', compact('cards'));
}
